import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.DJVIMu25.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ"},"headers":[],"relativePath":"en/reference/faq.md","filePath":"en/reference/faq.md","lastUpdated":1786545590000}'),i={name:"en/reference/faq.md"};function n(r,e,d,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Frequently asked questions about using JoyMart. Click a question to expand its answer.</p><details class="details custom-block"><summary>Q: Player&#39;s inventory cleared after entering a game?</summary><p><strong>A:</strong> This is by design — JoyMart saves and clears the inventory on entry, and restores it on leave. If a server crash prevented restoration, restart and have the player enter then leave JoyMart once to recover it.</p></details><details class="details custom-block"><summary>Q: Multiplayer invitation sent but recipient didn&#39;t get it?</summary><p><strong>A:</strong> Check <code>config.yml</code>&#39;s <code>invitations.style</code> setting (<code>json</code> / <code>actionbar</code> / <code>title</code>), and whether the recipient is on the same server (cross-server invitations require MySQL mode + BungeeCord event forwarding — this version does not include built-in cross-server invitation forwarding).</p></details><details class="details custom-block"><summary>Q: Shop items don&#39;t respond when clicked?</summary><p><strong>A:</strong> Check <code>tokenShop.yml</code> for correct indentation, and that the item&#39;s <code>buyPermission</code> is properly assigned by your permission plugin.</p></details><details class="details custom-block"><summary>Q: Cursor item disappeared when listing/unlisting?</summary><p><strong>A:</strong> Earlier versions modified the cursor synchronously inside <code>InventoryClickEvent</code>, which conflicted with client prediction and caused the item to &quot;vanish&quot;. This version wraps all cursor modifications and <code>build()</code> calls inside <code>Bukkit.getScheduler().runTask()</code>, deferring them to the next tick to fully resolve the issue. If you still encounter it, confirm your jar is the latest build.</p><p>See <a href="./../guides/configuration#shop-management-gui">Configuration Files - Shop Management GUI</a> for the &quot;listing / unlisting fix&quot; notes.</p></details><details class="details custom-block"><summary>Q: How to edit lottery/slot machine prizes?</summary><p><strong>A:</strong> An admin runs <code>/gba games</code> → picks the game → clicks the <strong>Prize Pool</strong> button to visually add/remove prizes, adjust weights and rewards in the GUI. Saving writes the result to the corresponding game&#39;s <code>config.yml</code> automatically — no manual editing needed.</p><p>See <a href="./../guides/configuration#prize-pool">Configuration Files - Lottery / Slot Machine Prize Pool</a> for the prize-pool config format.</p></details><details class="details custom-block"><summary>Q: Maze too easy/hard?</summary><p><strong>A:</strong> The maze size is hard-coded to 9×9 (recursive backtracking guarantees a unique path). To change it, modify the <code>n</code> constant in <code>MazeSession.java</code> and rebuild.</p></details><details class="details custom-block"><summary>Q: How to add own language?</summary><p><strong>A:</strong> Copy <code>plugins/JoyMart/language/language_en.yml</code> to <code>language_xx.yml</code>, translate all keys, and set <code>language.default: xx</code> in <code>config.yml</code>. Game-specific language files live in <code>language/game_&lt;game&gt;/language_xx.yml</code> — copy and translate the same way.</p></details><details class="details custom-block"><summary>Q: Set Chinese but game still shows English?</summary><p><strong>A:</strong> Make sure <code>language.default: zh</code> in <code>config.yml</code>, then run <code>/gba reload</code>. The plugin will copy <code>language_zh.yml</code> and each game&#39;s <code>language_zh.yml</code> to the <code>plugins/JoyMart/language/</code> directory automatically.</p></details>',10)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
